/** Collection of functions, objects, and types that are used as helpers in other services. */

// Thanks to blubberdiblub at https://stackoverflow.com/a/68141099/217579
export function newGuid(): string {
  return '00-0-4-1-000'.replace(/[^-]/g, (s) =>
    // @ts-expect-error ts(2363) this works fine
    // eslint-disable-next-line no-bitwise
    (((Math.random() + ~~s) * 0x10000) >> s).toString(16).padStart(4, '0'),
  );
}

// thanks to DRAX at https://stackoverflow.com/a/9436948
/**
 * Determine whether the object is a string
 *
 * @param o Object to determine if it is a string
 * @returns True if the object is a string; false otherwise
 */
export function isString(o: unknown): o is string {
  return typeof o === 'string' || o instanceof String;
}

/**
 * If deepClone isn't used when copying properties between objects, you may be left with dangling
 * references between the source and target of property copying operations.
 *
 * @param obj Object to clone
 * @returns Duplicate copy of `obj` without any references back to the original one
 */
export function deepClone<T>(obj: T): T {
  // Assert the return type matches what is expected
  // eslint-disable-next-line no-type-assertion/no-type-assertion
  return JSON.parse(JSON.stringify(obj)) as T;
}

/**
 * Message of the error with which a pending debounced invocation's promise rejects when
 * {@link DebouncedFunction.cancel} is called. Compare a caught error's message against this to
 * distinguish cancellation from real errors.
 */
export const DEBOUNCE_CANCELED_ERROR_MESSAGE = 'Debounced function invocation was canceled';

/**
 * A debounced function with `cancel` and `flush` methods to abandon or immediately run any pending
 * invocation (lodash-style lifecycle controls).
 *
 * @template TFunc - The type of the function being debounced.
 */
// We don't know the parameter types since this function can be anything and can return anything
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export type DebouncedFunction<TFunc extends (...args: any[]) => any> = ((
  ...args: Parameters<TFunc>
) => Promise<ReturnType<TFunc>>) & {
  /**
   * Cancel any pending debounced invocation. The promise returned by the most recent call rejects
   * with an error whose message is {@link DEBOUNCE_CANCELED_ERROR_MESSAGE}.
   *
   * IMPORTANT: because cancellation _rejects_ that promise, every call whose result you might later
   * cancel MUST handle its rejection (await in a try/catch, or attach a `.catch`, filtering on
   * {@link DEBOUNCE_CANCELED_ERROR_MESSAGE} to distinguish cancellation from a real error).
   * Fire-and-forget callers that ignore the returned promise will get an unhandled promise
   * rejection when `cancel()` runs.
   */
  cancel: () => void;
  /**
   * Run the pending debounced invocation NOW (synchronously, with the most recently passed
   * arguments) instead of waiting out the remaining delay, and clear the timer so it does not fire
   * a second time.
   *
   * Useful at lifecycle boundaries where the trailing window would otherwise lose the final
   * invocation (unmount, blur, pagehide) or run it against changed context (see the
   * platform-scripture-editor extension's debounced PDP save).
   *
   * @returns The same promise the pending calls received (resolving/rejecting with the flushed
   *   invocation's outcome), or `undefined` when nothing was pending (in which case nothing runs).
   */
  flush: () => Promise<ReturnType<TFunc>> | undefined;
};

/**
 * Get a function that reduces calls to the function passed in
 *
 * @template TFunc - A function type that takes any arguments and returns void. This is the type of
 *   the function being debounced.
 * @param fn The function to debounce
 * @param delay How much delay in milliseconds after the most recent call to the debounced function
 *   to call the function
 * @returns Function that, when called, only calls the function passed in at maximum every delay ms.
 *   The returned function also has a `cancel` method to abandon any pending invocation (canceling
 *   makes the pending invocation's promise reject with an error whose message is
 *   {@link DEBOUNCE_CANCELED_ERROR_MESSAGE}) and a `flush` method to run the pending invocation
 *   immediately instead of waiting out the delay.
 */
// We don't know the parameter types since this function can be anything and can return anything
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export function debounce<TFunc extends (...args: any[]) => any>(
  fn: TFunc,
  delay = 300,
): DebouncedFunction<TFunc> {
  let timeout: ReturnType<typeof setTimeout>;
  let promise: Promise<ReturnType<TFunc>> | undefined;
  let promiseResolve: (value: ReturnType<TFunc> | PromiseLike<ReturnType<TFunc>>) => void;
  let promiseReject: (reason?: unknown) => void;
  // The most recently passed arguments while an invocation is pending; undefined when none is.
  // Shared between the trailing-edge timer and `flush` so both run exactly the same invocation.
  let pendingArgs: Parameters<TFunc> | undefined;

  // The promise every caller waiting on the currently pending invocation shares, minted on demand
  // so an invocation always has exactly one promise to settle.
  const pendingPromise = (): Promise<ReturnType<TFunc>> => {
    if (!promise)
      promise = new Promise((resolve, reject) => {
        promiseResolve = resolve;
        promiseReject = reject;
      });
    return promise;
  };

  // Runs one invocation with the given args, settling the promise that is pending as it starts.
  // `fn` itself is invoked synchronously (before any await), which is what lets `flush` run the
  // pending call even in teardown paths (pagehide/beforeunload) where async work never resumes.
  //
  // The promise and its settlers are captured AT ENTRY and the stored promise is detached
  // immediately, before the first await: this invocation's outcome must reach the callers who were
  // waiting on IT, and a call arriving while it settles is a DIFFERENT invocation that needs its
  // own promise. One promise shared across both would settle the newer caller with the older
  // call's result and discard the newer outcome — including a rejection — unobserved.
  const runInvocation = async (args: Parameters<TFunc>): Promise<void> => {
    const resolveInvocation = promiseResolve;
    const rejectInvocation = promiseReject;
    promise = undefined;
    try {
      resolveInvocation(await fn(...args));
    } catch (e) {
      rejectInvocation(e);
    }
  };

  const debouncedFn = (...args: Parameters<TFunc>): Promise<ReturnType<TFunc>> => {
    clearTimeout(timeout);
    const callPromise = pendingPromise();

    pendingArgs = args;
    timeout = setTimeout(() => {
      const argsToRun = pendingArgs;
      // Cleared BEFORE invoking so a re-schedule from inside `fn` is not wiped out
      pendingArgs = undefined;
      if (argsToRun) runInvocation(argsToRun);
    }, delay);

    return callPromise;
  };

  debouncedFn.cancel = () => {
    clearTimeout(timeout);
    pendingArgs = undefined;
    if (promise) {
      promiseReject(new Error(DEBOUNCE_CANCELED_ERROR_MESSAGE));
      promise = undefined;
    }
  };

  debouncedFn.flush = () => {
    if (pendingArgs === undefined) return undefined;
    clearTimeout(timeout);
    const argsToRun = pendingArgs;
    // Cleared BEFORE invoking so a re-schedule from inside `fn` is not wiped out
    pendingArgs = undefined;
    // Pending args always have a promise to settle, but not always a stored one: a call made while
    // the previous invocation was settling leaves args pending after that invocation detached the
    // promise. Minting here keeps flush's contract — it returns `undefined` only when nothing runs.
    const flushedPromise = pendingPromise();
    runInvocation(argsToRun);
    return flushedPromise;
  };

  // Type assertion is necessary to cast the internal implementation type to the public API type
  // eslint-disable-next-line no-type-assertion/no-type-assertion
  return debouncedFn as DebouncedFunction<TFunc>;
}

/**
 * Groups each item in the array of items into a map according to the keySelector
 *
 * There are two overloads:
 *
 * - `groupBy(items, keySelector)` – groups the original items using the key returned by
 *   `keySelector`.
 * - `groupBy(items, keySelector, valueSelector)` – groups transformed values using the key returned
 *   by `keySelector` and the value returned by `valueSelector`.
 *
 * `valueSelector` is an optional third parameter. It is a function that runs on each item to get
 * the value to store in the group. The first argument is the item, the second argument is the key
 * for the group to which this item belongs, and the third argument is the index of the item in the
 * original array. If `valueSelector` is not provided, the original item is used in the resulting
 * groups.
 *
 * @param items - Array of items to group by.
 * @param keySelector - Function to run on each item to get the key for the group to which it
 *   belongs. The first argument is the item, and the second argument is the index of the item in
 *   the original array.
 * @returns Map of keys to groups of values corresponding to each item.
 */
export function groupBy<T, K>(
  items: T[],
  keySelector: (item: T, index: number) => K,
): Map<K, Array<T>>;
export function groupBy<T, K, V>(
  items: T[],
  keySelector: (item: T, index: number) => K,
  valueSelector: (item: T, key: K, index: number) => V,
): Map<K, Array<V>>;
export function groupBy<T, K, V = T>(
  items: T[],
  keySelector: (item: T, index: number) => K,
  valueSelector?: (item: T, key: K, index: number) => V,
): Map<K, Array<V | T>> {
  const map = new Map<K, Array<V | T>>();
  items.forEach((item, index) => {
    const key = keySelector(item, index);
    const group = map.get(key);
    const value = valueSelector ? valueSelector(item, key, index) : item;
    if (group) group.push(value);
    else map.set(key, [value]);
  });
  return map;
}

// From https://kentcdodds.com/blog/get-a-catch-block-error-message-with-typescript
type ErrorWithMessage = {
  message: string;
};

// From https://kentcdodds.com/blog/get-a-catch-block-error-message-with-typescript
function isErrorWithMessage(error: unknown): error is ErrorWithMessage {
  return (
    typeof error === 'object' &&
    // We're potentially dealing with objects we didn't create, so they might contain `null`
    // eslint-disable-next-line no-null/no-null
    error !== null &&
    'message' in error &&
    // Type assert `error` to check it's `message`.
    // eslint-disable-next-line no-type-assertion/no-type-assertion
    typeof (error as Record<string, unknown>).message === 'string'
  );
}

// From https://kentcdodds.com/blog/get-a-catch-block-error-message-with-typescript
/**
 * Function to get an error from the object (useful for getting an error in a catch block)
 *
 * @param error Error object whose message to get
 * @returns Message of the error - if object has message, returns message. Otherwise tries to
 *   stringify
 */
function toErrorWithMessage(maybeError: unknown): ErrorWithMessage {
  if (isErrorWithMessage(maybeError)) return maybeError;

  try {
    return new Error(JSON.stringify(maybeError));
  } catch {
    // fallback in case there's an error stringifying the maybeError
    // like with circular references for example.
    return new Error(String(maybeError));
  }
}

// From https://kentcdodds.com/blog/get-a-catch-block-error-message-with-typescript
/**
 * Function to get an error message from the object (useful for getting error message in a catch
 * block)
 *
 * @example `try {...} catch (e) { logger.info(getErrorMessage(e)) }`
 *
 * @param error Error object whose message to get
 * @returns Message of the error - if object has message, returns message. Otherwise tries to
 *   stringify
 */
export function getErrorMessage(error: unknown) {
  return toErrorWithMessage(error).message;
}

/** Asynchronously waits for the specified number of milliseconds. (wraps setTimeout in a promise) */
export function wait(ms: number) {
  // setTimeout returns a value but the Promise executor must not; returning it directly is the cleanest form
  // eslint-disable-next-line no-promise-executor-return
  return new Promise<void>((resolve) => setTimeout(resolve, ms));
}

/**
 * Runs the specified function and will timeout if it takes longer than the specified wait time
 *
 * @param fn The function to run
 * @param maxWaitTimeInMS The maximum amount of time to wait for the function to resolve
 * @returns Promise that resolves to the resolved value of the function or undefined if it ran
 *   longer than the specified wait time
 */
export function waitForDuration<TResult>(fn: () => Promise<TResult>, maxWaitTimeInMS: number) {
  const timeout = wait(maxWaitTimeInMS).then(() => undefined);
  return Promise.any([timeout, fn()]);
}

/**
 * Repeatedly runs an async attempt until its result is accepted or the attempt budget is exhausted,
 * waiting a fixed delay between tries (never after the last). Always resolves to the last result —
 * it never throws on exhaustion, so the caller decides what a give-up result means.
 *
 * This is the fixed-attempts + fixed-delay retry shape shared by flaky-startup probes (e.g.
 * `resolveRegistrationValidity`, and the missing-handler retry in `requestWithRetry`). For
 * deadline- or abort-driven retries with variable backoff (e.g. `requestSessionSyncWithBootRetry`
 * in startup-tasks), use a bespoke loop instead — this helper deliberately does not cover those.
 *
 * @param attempt Runs one try; receives the 1-based attempt number and resolves to a result.
 * @param isDone Returns `true` when `attempt`'s result is acceptable and retrying should stop.
 * @param options.maxAttempts Total tries; clamped to at least 1. Defaults to 3.
 * @param options.delayMs Delay between tries. Defaults to 0.
 * @returns The first accepted result, or the last attempt's result if none qualified.
 */
export async function retryUntil<TResult>(
  attempt: (attemptNumber: number) => Promise<TResult>,
  isDone: (result: TResult) => boolean,
  options?: { maxAttempts?: number; delayMs?: number },
): Promise<TResult> {
  const maxAttempts = Math.max(1, options?.maxAttempts ?? 3);
  const delayMs = options?.delayMs ?? 0;
  let attemptNumber = 1;
  for (;;) {
    // Await inside the loop on purpose: try one at a time so each retry gives whatever we're waiting
    // on more time to become ready.
    // eslint-disable-next-line no-await-in-loop
    const result = await attempt(attemptNumber);
    // Return before the backoff on both success and the final attempt, so we never wait after the
    // last try.
    if (isDone(result) || attemptNumber >= maxAttempts) return result;
    attemptNumber += 1;
    // Await inside the loop on purpose: back off before the next attempt.
    // eslint-disable-next-line no-await-in-loop
    await wait(delayMs);
  }
}

/**
 * Get all functions on an object and its prototype chain (so we don't miss any class methods or any
 * object methods). Note that the functions on the final item in the prototype chain (i.e., Object)
 * are skipped to avoid including functions like `__defineGetter__`, `__defineSetter__`, `toString`,
 * etc.
 *
 * @param obj Object whose functions to get
 * @param _objId Optional ID of the object to use for debug logging
 * @returns Array of all function names on an object
 */
// Note: lodash has something that MIGHT do the same thing as this. Investigate for https://github.com/paranext/paranext-core/issues/134
export function getAllObjectFunctionNames(
  obj: { [property: string]: unknown },
  // Leaving it here for debugging
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  _objId: string = 'obj',
): Set<string> {
  const objectFunctionNames = new Set<string>();

  // Get all function properties directly defined on the object
  Object.getOwnPropertyNames(obj).forEach((property) => {
    try {
      if (typeof obj[property] === 'function') objectFunctionNames.add(property);
    } catch {
      // Too noisy - only reenable if you need more details
      // console.trace(`Skipping ${property} on ${objId} due to error: ${error}`);
    }
  });

  // Walk up the prototype chain and get additional function properties, skipping the functions
  // provided by the final (Object) prototype
  let objectPrototype = Object.getPrototypeOf(obj);
  while (objectPrototype && Object.getPrototypeOf(objectPrototype)) {
    Object.getOwnPropertyNames(objectPrototype).forEach((property) => {
      try {
        if (typeof obj[property] === 'function') objectFunctionNames.add(property);
      } catch {
        // Too noisy - only reenable if you need more details
        // console.trace(`Skipping ${property} on ${objId}'s prototype due to error`);
      }
    });
    objectPrototype = Object.getPrototypeOf(objectPrototype);
  }

  return objectFunctionNames;
}

/**
 * Creates a synchronous proxy for an asynchronous object. The proxy allows calling methods on an
 * object that is asynchronously fetched using a provided asynchronous function.
 *
 * @param getObject - A function that returns a promise resolving to the object whose asynchronous
 *   methods to call.
 * @param objectToProxy - An optional object that is the object that is proxied. If a property is
 *   accessed that does exist on this object, it will be returned. If a property is accessed that
 *   does not exist on this object, it will be considered to be an asynchronous method called on the
 *   object returned from getObject.
 * @returns A synchronous proxy for the asynchronous object.
 */
export function createSyncProxyForAsyncObject<T extends object>(
  getObject: (args?: unknown[]) => Promise<T>,
  objectToProxy: Partial<T> = {},
): T {
  // objectToProxy will have only the synchronously accessed properties of T on it, and this proxy
  // makes the async methods that do not exist yet available synchronously so we have all of T
  // eslint-disable-next-line no-type-assertion/no-type-assertion
  return new Proxy(objectToProxy as T, {
    get(target, prop) {
      // We don't have any type information for T, so we assume methodName exists on it and will let JavaScript throw if it doesn't exist
      // @ts-expect-error 7053
      if (prop in target) return target[prop];
      return async (...args: unknown[]) => {
        // 7053: We don't have any type information for T, so we assume methodName exists on it and will let JavaScript throw if it doesn't exist
        // 2556: The args here are the parameters for the method specified
        // @ts-expect-error 7053 2556
        return (await getObject())[prop](...args);
      };
    },
  });
}

/**
 * Indicates if the exception or error message provided appears to be from ParatextData.dll
 * indicating that Paratext is blocking internet access.
 *
 * @param errorMessage Error message or exception to check
 * @returns `true` if the message indicates Paratext is blocking internet access, `false` otherwise
 */
export function isErrorMessageAboutParatextBlockingInternetAccess(errorMessage: unknown): boolean {
  // Copied from ParatextData/InternetAccess.cs, not a localized string
  const paratextExceptionMessage =
    'Bug in Paratext caused attempted access to Internet. Request has been blocked.';

  if (isString(errorMessage)) return errorMessage.includes(paratextExceptionMessage);
  return getErrorMessage(errorMessage).includes(paratextExceptionMessage);
}

/**
 * Indicates if the exception or error message provided appears to be from ParatextData.dll
 * indicating that an authorization failure occurred regarding registry credentials.
 *
 * @param errorMessage Error message or exception to check
 * @returns `true` if the message indicates an auth failure, `false` otherwise
 */
export function isErrorMessageAboutRegistryAuthFailure(errorMessage: unknown): boolean {
  // Copied from ParatextProjectSendReceiveService.cs, not a localized string
  const paratextExceptionMessage1 = '401 Unauthorized error while getting shared projects.';
  // Copied from DblDownloadableDataProvider.cs, not a localized string
  const paratextExceptionMessage2 =
    'User registration is not valid. Cannot retrieve resources from DBL.';

  const errorString = isString(errorMessage) ? errorMessage : getErrorMessage(errorMessage);
  return (
    errorString.includes(paratextExceptionMessage1) ||
    errorString.includes(paratextExceptionMessage2)
  );
}

/** Within type T, recursively change all properties to be optional */
export type DeepPartial<T> = T extends object ? { [P in keyof T]?: DeepPartial<T[P]> } : T;

/** Within type T, recursively change properties that were of type A to be of type B */
export type ReplaceType<T, A, B> = T extends A
  ? B
  : T extends object
    ? { [K in keyof T]: ReplaceType<T[K], A, B> }
    : T;

/**
 * Converts a string type from camelCase to kebab-case. Note this simply inserts hyphens before
 * uppercase letters and converts them to lowercase. It does not handle special cases like acronyms
 * or symbols. It can result in multiple hyphens in a row, leading hyphens, or trailing hyphens.
 *
 * By using this as the type for a string parameter or string property, you can enforce (somewhat)
 * at compile time that the string is in kebab-case format assuming it is provided as a string
 * literal.
 *
 * @example
 *
 * ```typescript
 * type Kebab1 = KebabCase<'backgroundColor'>; // 'background-color'
 * type Kebab2 = KebabCase<'HTMLParser'>; // '-h-t-m-l-parser'
 * type Kebab3 = KebabCase<'simpletest'>; // 'simpletest'
 * type Kebab4 = KebabCase<'My$Value'>; // '-my$-value'
 * ```
 */
export type KebabCase<T extends string> = T extends `${infer First}${infer Rest}`
  ? `${First extends Lowercase<First> ? First : `-${Lowercase<First>}`}${KebabCase<Rest>}`
  : T;

// Thanks to jcalz at https://stackoverflow.com/a/50375286
/**
 * Converts a union type to an intersection type (`|` to `&`).
 *
 * Note: this utility type is for use on object types. It may fail on other types.
 *
 * @example
 *
 * ```typescript
 * type TypeOne = { one: string };
 * type TypeTwo = { two: number };
 * type TypeThree = { three: string };
 *
 * type TypeNums = { one: TypeOne; two: TypeTwo; three: TypeThree };
 * const numNames = ['one', 'two'] as const;
 * type TypeNumNames = typeof numNames;
 *
 * // Same as `TypeOne | TypeTwo`
 * // `{ one: string } | { two: number }`
 * type TypeOneTwoUnion = TypeNums[TypeNumNames[number]];
 *
 * // Same as `TypeOne & TypeTwo`
 * // `{ one: string; two: number }`
 * type TypeOneTwoIntersection = UnionToIntersection<TypeOneTwoUnion>;
 * ```
 */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export type UnionToIntersection<U> = (U extends any ? (x: U) => void : never) extends (
  x: infer I,
) => void
  ? I
  : never;

/**
 * Force VSCode to expand all the properties of a type by using this type. Useful for making complex
 * types more readable in hover tooltips.
 *
 * @example
 *
 * ```ts
 * type MyType = Prettify<SomeComplexType>;
 * ```
 */
export type Prettify<T> = {
  [K in keyof T]: T[K];
} & {};
